def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); rects=[]
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                            seen.add((yy,xx)); stack.append((yy,xx))
            rh=max(y for y,x in cells)-min(y for y,x in cells)+1
            rw=max(x for y,x in cells)-min(x for y,x in cells)+1
            if len(cells)==rh*rw: rects.append((len(cells),rh,rw))
    if rects:
        _,rh,rw=max(rects)
        return [[0]*rw for _ in range(rh)]
    return [[0]]

